```python
import math


def select_position(values, amount, scale):
    try:
        data = list(values)
    except TypeError as exc:
        raise TypeError("values must be iterable") from exc
    if not data:
        raise ValueError("values must not be empty")

    checked = []
    for value in data:
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("values must be numeric")
        if not math.isfinite(value):
            raise ValueError("values must be finite")
        checked.append(float(value))

    if isinstance(amount, bool) or not isinstance(amount, (int, float)):
        raise TypeError("amount must be numeric")
    if not math.isfinite(amount):
        raise ValueError("amount must be finite")
    if scale not in {"fraction", "percent"}:
        raise ValueError("invalid scale")

    upper = 1 if scale == "fraction" else 100
    if not 0 <= amount <= upper:
        raise ValueError("amount is out of range")
    q = float(amount)

    checked.sort()
    position = q * (len(checked) - 1)
    lower = math.floor(position)
    upper_index = math.ceil(position)
    if lower == upper_index:
        return checked[lower]
    weight = position - lower
    return checked[lower] * (1 - weight) + checked[upper_index] * weight
```

